                return monthIsValid(mm) ? `${yyyy}-${mm}-01` : '';
            }

            match = valor.match(/^01-(\d{2})-(\d{4})$/);
            if (match) {
                const [, mm, yyyy] = match;
                return monthIsValid(mm) ? `${yyyy}-${mm}-01` : '';
            }

            return '';
        }

